// Fictional component product imagery, embedded for offline rendering.
public static class PartArt {
    static readonly string[] keys={"front","rear","floor","diffuser","mono","nose","sidepods","suspF","suspR","brakes","radiators","ducts","gearbox","electronics","hydraulics"};
    static readonly int[] columns={0,419,837,1254},rows={0,248,482,712,953,1254};
    static readonly System.Collections.Generic.Dictionary<string,Bitmap> frames=new System.Collections.Generic.Dictionary<string,Bitmap>();
    static readonly Image atlas=Load();
    static Image Load(){using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("partatlas")){if(stream==null)throw new InvalidOperationException("Отсутствует встроенное изображение деталей.");using(var image=Image.FromStream(stream))return new Bitmap(image);}}
    public static bool Contains(string key){return Array.IndexOf(keys,key)>=0&&atlas!=null;}
    public static void Draw(Graphics g,string key,Rectangle rect){int index=Array.IndexOf(keys,key);if(index<0||rect.Width<1||rect.Height<1)return;string id=key+"/"+rect.Width+"/"+rect.Height;Bitmap frame;if(!frames.TryGetValue(id,out frame)){if(frames.Count>=96){foreach(var old in frames.Values)old.Dispose();frames.Clear();}frame=new Bitmap(rect.Width,rect.Height);int col=index%3,row=index/3;var source=new Rectangle(columns[col]+2,rows[row]+2,columns[col+1]-columns[col]-5,rows[row+1]-rows[row]-5);using(var canvas=Graphics.FromImage(frame)){canvas.Clear(Theme.Card);canvas.InterpolationMode=InterpolationMode.HighQualityBicubic;double scale=Math.Min(rect.Width/(double)source.Width,rect.Height/(double)source.Height);var dest=new Rectangle((int)((rect.Width-source.Width*scale)/2),(int)((rect.Height-source.Height*scale)/2),(int)(source.Width*scale),(int)(source.Height*scale));canvas.DrawImage(atlas,dest,source,GraphicsUnit.Pixel);}frames.Add(id,frame);}var saved=g.Save();using(var path=Theme.Round(rect,8))g.SetClip(path,CombineMode.Intersect);g.DrawImageUnscaled(frame,rect.Location);g.Restore(saved);}
}
public class PartPicture:Control {public string PartKey;public PartPicture(string key){PartKey=key;DoubleBuffered=true;BackColor=Theme.Card;}protected override void OnPaint(PaintEventArgs e){PartArt.Draw(e.Graphics,PartKey,ClientRectangle);}}
