ex){error.Text=ex.Message;}};BackButton.Click+=(o,e)=>Cancel();UpdateEstimate();}
    void UpdateEstimate(){var project=Engine.Estimate(state,part,(int)Engineers.Value,nextYear);estimate.Text="Стоимость: "+Engine.Money(project.Cost)+"\nПроектирование: "+(project.DesignEnd-state.Day)+" дн.\nПроизводство: "+(project.Due-project.DesignEnd)+" дн.\nПоставка: день "+project.Due+"\nРиск провала стенда: "+(project.Failure*100).ToString("0.0")+"%";var effects=CarModel.Effects(part.Key,project.Gain,focus);impacts.Text="ОЖИДАЕМЫЕ ИЗМЕНЕНИЯ\n"+string.Join("\n",Enumerable.Range(0,10).Where(i=>effects[i]!=0).Select(i=>CarModel.Names[i]+"  "+effects[i].ToString("+0.00;-0.00;0")));}
    public override void Cancel(){if(!Closing&&Cancelled!=null)Cancelled();}
}
